WITH filtered AS (SELECT id, customer_id, account_type, balance, opened_date, status, LOWER(account_type) AS account_type_lower FROM accounts WHERE status = 'OPEN') SELECT id, customer_id, opened_date, account_type_lower, LEAD(balance) OVER (PARTITION BY customer_id ORDER BY balance ASC, id ASC) AS next_balance, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY balance ASC, id ASC) AS seq_no, SUM(balance) OVER (ORDER BY opened_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_balance FROM filtered
